VALID_MEALS = {"breakfast", "lunch", "snacks", "dinner"}
VALID_DAYS = {"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"}

def is_valid_item(day: str, meal: str, item_id: str) -> bool:
    return (day in VALID_DAYS and meal in VALID_MEALS and
            item_id in VALID_ITEMS.get(day, {}).get(meal, set()))
